    14  bool OpenTypeSILF::Parse(const uint8_t* data, size_t length,
    15                           bool prevent_decompression) {
    16    Buffer table(data, length);
    17
    18    if (!table.ReadU32(&this->version)) {
    19      return DropGraphite("Failed to read version");
    20    }
    21    if (this->version >> 16 != 1 &&
    22        this->version >> 16 != 2 &&
    23        this->version >> 16 != 3 &&
    24        this->version >> 16 != 4 &&
    25        this->version >> 16 != 5) {
    26      return DropGraphite("Unsupported table version: %u", this->version >> 16);
    27    }
    28    if (this->version >> 16 >= 3 && !table.ReadU32(&this->compHead)) {
    29      return DropGraphite("Failed to read compHead");
    30    }
    31    if (this->version >> 16 >= 5) {
    32      switch ((this->compHead & SCHEME) >> 27) {
    33        case 0:  // uncompressed
    34          break;
    35        case 1: {  // lz4
    36          if (prevent_decompression) {
    37            return DropGraphite("Illegal nested compression");
    38          }
    39          size_t decompressed_size = this->compHead & FULL_SIZE;
    40          if (decompressed_size < length) {
    41            return DropGraphite("Decompressed size is less than compressed size");
    42          }
    43          if (decompressed_size == 0) {
    44            return DropGraphite("Decompressed size is set to 0");
    45          }
    46          // decompressed table must be <= OTS_MAX_DECOMPRESSED_TABLE_SIZE
    47          if (decompressed_size > OTS_MAX_DECOMPRESSED_TABLE_SIZE) {
    48            return DropGraphite("Decompressed size exceeds %gMB: %gMB",
    49                                OTS_MAX_DECOMPRESSED_TABLE_SIZE / (1024.0 * 1024.0),
    50                                decompressed_size / (1024.0 * 1024.0));
    51          }
    52          std::unique_ptr<uint8_t> decompressed(new uint8_t[decompressed_size]);
    53          int ret = LZ4_decompress_safe_partial(
    54              reinterpret_cast<const char*>(data + table.offset()),
    55              reinterpret_cast<char*>(decompressed.get()),
    56              table.remaining(),  // input buffer size (input size + padding)
    57              decompressed_size,  // target output size
    58              decompressed_size);  // output buffer size
    59          if (ret < 0 || unsigned(ret) != decompressed_size) {
    60            return DropGraphite("Decompression failed with error code %d", ret);
    61          }
    62          return this->Parse(decompressed.get(), decompressed_size, true);
    63        }
    64        default:
    65          return DropGraphite("Unknown compression scheme");
    66      }
    67    }
    68    if (!table.ReadU16(&this->numSub)) {
    69      return DropGraphite("Failed to read numSub");
    70    }
    71    if (this->version >> 16 >= 2 && !table.ReadU16(&this->reserved)) {
    72      return DropGraphite("Failed to read reserved");
    73    }
    74    if (this->version >> 16 >= 2 && this->reserved != 0) {
    75      Warning("Nonzero reserved");
    76    }
    77
    78    unsigned long last_offset = 0;
    79    //this->offset.resize(this->numSub);
    80    for (unsigned i = 0; i < this->numSub; ++i) {
    81      this->offset.emplace_back();
    82      if (!table.ReadU32(&this->offset[i]) || this->offset[i] < last_offset) {
    83        return DropGraphite("Failed to read offset[%u]", i);
    84      }
    85      last_offset = this->offset[i];
    86    }
    87
    88    for (unsigned i = 0; i < this->numSub; ++i) {
    89      if (table.offset() != this->offset[i]) {
    90        return DropGraphite("Offset check failed for tables[%lu]", i);
    91      }
    92      SILSub subtable(this);
    93      if (!subtable.ParsePart(table)) {
    94        return DropGraphite("Failed to read tables[%u]", i);
    95      }
    96      tables.push_back(subtable);
    97    }
    98
    99    if (table.remaining()) {
   100      return Warning("%zu bytes unparsed", table.remaining());
   101    }
   102    return true;
   103  }
