   105  bool OpenTypeSILF::Serialize(OTSStream* out) {
   106    if (!out->WriteU32(this->version) ||
   107        (this->version >> 16 >= 3 && !out->WriteU32(this->compHead)) ||
   108        !out->WriteU16(this->numSub) ||
   109        (this->version >> 16 >= 2 && !out->WriteU16(this->reserved)) ||
   110        !SerializeParts(this->offset, out) ||
   111        !SerializeParts(this->tables, out)) {
   112      return Error("Failed to write table");
   113    }
   114    return true;
   115  }
