   117  bool OpenTypeSILF::SILSub::ParsePart(Buffer& table) {
   118    size_t init_offset = table.offset();
   119    if (parent->version >> 16 >= 3) {
   120      if (!table.ReadU32(&this->ruleVersion)) {
   121        return parent->Error("SILSub: Failed to read ruleVersion");
   122      }
   123      if (!table.ReadU16(&this->passOffset)) {
   124        return parent->Error("SILSub: Failed to read passOffset");
   125      }
   126      if (!table.ReadU16(&this->pseudosOffset)) {
   127        return parent->Error("SILSub: Failed to read pseudosOffset");
   128      }
   129    }
   130    if (!table.ReadU16(&this->maxGlyphID)) {
   131      return parent->Error("SILSub: Failed to read maxGlyphID");
   132    }
   133    if (!table.ReadS16(&this->extraAscent)) {
   134      return parent->Error("SILSub: Failed to read extraAscent");
   135    }
   136    if (!table.ReadS16(&this->extraDescent)) {
   137      return parent->Error("SILSub: Failed to read extraDescent");
   138    }
   139    if (!table.ReadU8(&this->numPasses)) {
   140      return parent->Error("SILSub: Failed to read numPasses");
   141    }
   142    if (!table.ReadU8(&this->iSubst) || this->iSubst > this->numPasses) {
   143      return parent->Error("SILSub: Failed to read valid iSubst");
   144    }
   145    if (!table.ReadU8(&this->iPos) || this->iPos > this->numPasses) {
   146      return parent->Error("SILSub: Failed to read valid iPos");
   147    }
   148    if (!table.ReadU8(&this->iJust) || this->iJust > this->numPasses) {
   149      return parent->Error("SILSub: Failed to read valid iJust");
   150    }
   151    if (!table.ReadU8(&this->iBidi) ||
   152        !(iBidi == 0xFF || this->iBidi <= this->iPos)) {
   153      return parent->Error("SILSub: Failed to read valid iBidi");
   154    }
   155    if (!table.ReadU8(&this->flags)) {
   156      return parent->Error("SILSub: Failed to read flags");
   157      // checks omitted
   158    }
   159    if (!table.ReadU8(&this->maxPreContext)) {
   160      return parent->Error("SILSub: Failed to read maxPreContext");
   161    }
   162    if (!table.ReadU8(&this->maxPostContext)) {
   163      return parent->Error("SILSub: Failed to read maxPostContext");
   164    }
   165    if (!table.ReadU8(&this->attrPseudo)) {
   166      return parent->Error("SILSub: Failed to read attrPseudo");
   167    }
   168    if (!table.ReadU8(&this->attrBreakWeight)) {
   169      return parent->Error("SILSub: Failed to read attrBreakWeight");
   170    }
   171    if (!table.ReadU8(&this->attrDirectionality)) {
   172      return parent->Error("SILSub: Failed to read attrDirectionality");
   173    }
   174    if (parent->version >> 16 >= 2) {
   175      if (!table.ReadU8(&this->attrMirroring)) {
   176        return parent->Error("SILSub: Failed to read attrMirroring");
   177      }
   178      if (!table.ReadU8(&this->attrSkipPasses)) {
   179        return parent->Error("SILSub: Failed to read attrSkipPasses");
   180      }
   181
   182      if (!table.ReadU8(&this->numJLevels)) {
   183        return parent->Error("SILSub: Failed to read numJLevels");
   184      }
   185      //this->jLevels.resize(this->numJLevels, parent);
   186      for (unsigned i = 0; i < this->numJLevels; ++i) {
   187        this->jLevels.emplace_back(parent);
   188        if (!this->jLevels[i].ParsePart(table)) {
   189          return parent->Error("SILSub: Failed to read jLevels[%u]", i);
   190        }
   191      }
   192    }
   193
   194    if (!table.ReadU16(&this->numLigComp)) {
   195      return parent->Error("SILSub: Failed to read numLigComp");
   196    }
   197    if (!table.ReadU8(&this->numUserDefn)) {
   198      return parent->Error("SILSub: Failed to read numUserDefn");
   199    }
   200    if (!table.ReadU8(&this->maxCompPerLig)) {
   201      return parent->Error("SILSub: Failed to read maxCompPerLig");
   202    }
   203    if (!table.ReadU8(&this->direction)) {
   204      return parent->Error("SILSub: Failed to read direction");
   205    }
   206    if (!table.ReadU8(&this->attrCollisions)) {
   207      return parent->Error("SILSub: Failed to read attrCollisions");
   208    }
   209    if (parent->version < 0x40001 && this->attrCollisions != 0) {
   210      parent->Warning("SILSub: Nonzero attrCollisions (reserved before v4.1)");
   211    }
   212    if (!table.ReadU8(&this->reserved4)) {
   213      return parent->Error("SILSub: Failed to read reserved4");
   214    }
   215    if (this->reserved4 != 0) {
   216      parent->Warning("SILSub: Nonzero reserved4");
   217    }
   218    if (!table.ReadU8(&this->reserved5)) {
   219      return parent->Error("SILSub: Failed to read reserved5");
   220    }
   221    if (this->reserved5 != 0) {
   222      parent->Warning("SILSub: Nonzero reserved5");
   223    }
   224    if (parent->version >> 16 >= 2) {
   225      if (!table.ReadU8(&this->reserved6)) {
   226        return parent->Error("SILSub: Failed to read reserved6");
   227      }
   228      if (this->reserved6 != 0) {
   229        parent->Warning("SILSub: Nonzero reserved6");
   230      }
   231
   232      if (!table.ReadU8(&this->numCritFeatures)) {
   233        return parent->Error("SILSub: Failed to read numCritFeatures");
   234      }
   235      //this->critFeatures.resize(this->numCritFeatures);
   236      for (unsigned i = 0; i < this->numCritFeatures; ++i) {
   237        this->critFeatures.emplace_back();
   238        if (!table.ReadU16(&this->critFeatures[i])) {
   239          return parent->Error("SILSub: Failed to read critFeatures[%u]", i);
   240        }
   241      }
   242
   243      if (!table.ReadU8(&this->reserved7)) {
   244        return parent->Error("SILSub: Failed to read reserved7");
   245      }
   246      if (this->reserved7 != 0) {
   247        parent->Warning("SILSub: Nonzero reserved7");
   248      }
   249    }
   250
   251    if (!table.ReadU8(&this->numScriptTag)) {
   252      return parent->Error("SILSub: Failed to read numScriptTag");
   253    }
   254    //this->scriptTag.resize(this->numScriptTag);
   255    for (unsigned i = 0; i < this->numScriptTag; ++i) {
   256      this->scriptTag.emplace_back();
   257      if (!table.ReadU32(&this->scriptTag[i])) {
   258        return parent->Error("SILSub: Failed to read scriptTag[%u]", i);
   259      }
   260    }
