    70  struct Arena {
    71   public:
    72    ~Arena() {
    73      for (auto& hunk : hunks_) {
    74        delete[] hunk;
    75      }
    76    }
    77
    78    uint8_t* Allocate(size_t length) {
    79      uint8_t* p = new uint8_t[length];
    80      hunks_.push_back(p);
    81      return p;
    82    }
    83
    84   private:
    85    std::vector<uint8_t*> hunks_;
    86  };
