    24  template<typename T>
    25  bool SerializeParts(const std::vector<T>& vec, OTSStream* out) {
    26    for (const T& part : vec) {
    27      if (!part.SerializePart(out)) {
    28        return false;
    29      }
    30    }
    31    return true;
    32  }
