   262    if (!table.ReadU16(&this->lbGID)) {
   263      return parent->Error("SILSub: Failed to read lbGID");
   264    }
   265    if (this->lbGID > this->maxGlyphID) {
   266      parent->Warning("SILSub: lbGID %u outside range 0..%u, replaced with 0",
   267                      this->lbGID, this->maxGlyphID);
