   277    for (unsigned i = 0; i <= this->numPasses; ++i) {
   278      this->oPasses.emplace_back();
   279      if (!table.ReadU32(&this->oPasses[i]) || this->oPasses[i] < last_oPass) {
   280        return false;
   281      }
   282      last_oPass = this->oPasses[i];
   283    }
   284
   285    if (parent->version >> 16 >= 3 &&
   286        table.offset() != init_offset + this->pseudosOffset) {
   287      return parent->Error("SILSub: pseudosOffset check failed");
   288    }
   289    if (!table.ReadU16(&this->numPseudo)) {
   290      return parent->Error("SILSub: Failed to read numPseudo");
   291    }
   292
   293    // The following three fields are deprecated and ignored. We fix them up here
   294    // just for internal consistency, but the Graphite engine doesn't care.
   295    if (!table.ReadU16(&this->searchPseudo) ||
   296        !table.ReadU16(&this->pseudoSelector) ||
   297        !table.ReadU16(&this->pseudoShift)) {
   298      return parent->Error("SILSub: Failed to read searchPseudo..pseudoShift");
   299    }
   300    if (this->numPseudo == 0) {
   301      if (this->searchPseudo != 0 || this->pseudoSelector != 0 || this->pseudoShift != 0) {
   302        this->searchPseudo = this->pseudoSelector = this->pseudoShift = 0;
   303      }
   304    } else {
   305      unsigned floorLog2 = std::floor(std::log2(this->numPseudo));
   306      if (this->searchPseudo != 6 * (unsigned)std::pow(2, floorLog2) ||
   307          this->pseudoSelector != floorLog2 ||
   308          this->pseudoShift != 6 * this->numPseudo - this->searchPseudo) {
   309        this->searchPseudo = 6 * (unsigned)std::pow(2, floorLog2);
   310        this->pseudoSelector = floorLog2;
   311        this->pseudoShift = 6 * this->numPseudo - this->searchPseudo;
   312      }
   313    }
   314
   315    //this->pMaps.resize(this->numPseudo, parent);
   316    for (unsigned i = 0; i < numPseudo; i++) {
   317      this->pMaps.emplace_back(parent);
   318      if (!this->pMaps[i].ParsePart(table)) {
   319        return parent->Error("SILSub: Failed to read pMaps[%u]", i);
   320      }
   321    }
   322
   323    if (!this->classes.ParsePart(table)) {
   324      return parent->Error("SILSub: Failed to read classes");
   325    }
   326
   327    //this->passes.resize(this->numPasses, parent);
   328    for (unsigned i = 0; i < this->numPasses; ++i) {
   329      this->passes.emplace_back(parent);
   330      if (table.offset() != init_offset + this->oPasses[i]) {
   331        return parent->Error("SILSub: Offset check failed for passes[%u]", i);
   332      }
   333      if (!this->passes[i].ParsePart(table, init_offset, this->oPasses[i+1])) {
   334        return parent->Error("SILSub: Failed to read passes[%u]", i);
   335      }
   336    }
   337    return true;
   338  }
