   474  bool OpenTypeSILF::SILSub::
   475  ClassMap::ParsePart(Buffer& table) {
   476    size_t init_offset = table.offset();
   477    if (!table.ReadU16(&this->numClass)) {
   478      return parent->Error("ClassMap: Failed to read numClass");
   479    }
   480    if (!table.ReadU16(&this->numLinear) || this->numLinear > this->numClass) {
   481      return parent->Error("ClassMap: Failed to read valid numLinear");
   482    }
   483
   484    //this->oClass.resize(static_cast<unsigned long>(this->numClass) + 1);
   485    if (parent->version >> 16 >= 4) {
   486      unsigned long last_oClass = 0;
   487      for (unsigned long i = 0; i <= this->numClass; ++i) {
   488        this->oClass.emplace_back();
   489        if (!table.ReadU32(&this->oClass[i]) || this->oClass[i] < last_oClass) {
   490          return parent->Error("ClassMap: Failed to read oClass[%lu]", i);
   491        }
   492        last_oClass = this->oClass[i];
   493      }
   494    }
   495    if (parent->version >> 16 < 4) {
   496      unsigned last_oClass = 0;
   497      for (unsigned long i = 0; i <= this->numClass; ++i) {
   498        uint16_t offset;
   499        if (!table.ReadU16(&offset) || offset < last_oClass) {
   500          return parent->Error("ClassMap: Failed to read oClass[%lu]", i);
   501        }
   502        last_oClass = offset;
   503        this->oClass.push_back(static_cast<uint32_t>(offset));
   504      }
   505    }
   506
   507    if (table.offset() - init_offset > this->oClass[this->numLinear]) {
   508      return parent->Error("ClassMap: Failed to calculate length of glyphs");
   509    }
   510    unsigned long glyphs_len = (this->oClass[this->numLinear] -
   511                               (table.offset() - init_offset))/2;
   512    //this->glyphs.resize(glyphs_len);
   513    for (unsigned long i = 0; i < glyphs_len; ++i) {
   514      this->glyphs.emplace_back();
   515      if (!table.ReadU16(&this->glyphs[i])) {
   516        return parent->Error("ClassMap: Failed to read glyphs[%lu]", i);
   517      }
   518    }
   519
   520    unsigned lookups_len = this->numClass - this->numLinear;
   521      // this->numLinear <= this->numClass
   522    //this->lookups.resize(lookups_len, parent);
   523    for (unsigned i = 0; i < lookups_len; ++i) {
   524      this->lookups.emplace_back(parent);
   525      if (table.offset() != init_offset + oClass[this->numLinear + i]) {
   526        return parent->Error("ClassMap: Offset check failed for lookups[%u]", i);
   527      }
   528      if (!this->lookups[i].ParsePart(table)) {
   529        return parent->Error("ClassMap: Failed to read lookups[%u]", i);
   530      }
   531    }
   532    return true;
   533  }
