   535  bool OpenTypeSILF::SILSub::
   536  ClassMap::SerializePart(OTSStream* out) const {
   537    if (!out->WriteU16(this->numClass) ||
   538        !out->WriteU16(this->numLinear) ||
   539        (parent->version >> 16 >= 4 && !SerializeParts(this->oClass, out)) ||
   540        (parent->version >> 16 < 4 &&
   541         ![&] {
   542           for (uint32_t offset : this->oClass) {
   543             if (!out->WriteU16(static_cast<uint16_t>(offset))) {
   544               return false;
   545             }
   546           }
   547           return true;
   548         }()) ||
   549        !SerializeParts(this->glyphs, out) ||
   550        !SerializeParts(this->lookups, out)) {
   551      return parent->Error("ClassMap: Failed to write");
   552    }
   553    return true;
   554  }
