   903  bool OpenTypeSILF::SILSub::
   904  SILPass::SerializePart(OTSStream* out) const {
   905    if (!out->WriteU8(this->flags) ||
   906        !out->WriteU8(this->maxRuleLoop) ||
   907        !out->WriteU8(this->maxRuleContext) ||
   908        !out->WriteU8(this->maxBackup) ||
   909        !out->WriteU16(this->numRules) ||
   910        (parent->version >> 16 >= 2 &&
   911         (!out->WriteU16(this->fsmOffset) ||
   912          !out->WriteU32(this->pcCode))) ||
   913        !out->WriteU32(this->rcCode) ||
   914        !out->WriteU32(this->aCode) ||
   915        !out->WriteU32(this->oDebug) ||
   916        !out->WriteU16(this->numRows) ||
   917        !out->WriteU16(this->numTransitional) ||
   918        !out->WriteU16(this->numSuccess) ||
   919        !out->WriteU16(this->numColumns) ||
   920        !out->WriteU16(this->numRange) ||
   921        !out->WriteU16(this->searchRange) ||
   922        !out->WriteU16(this->entrySelector) ||
   923        !out->WriteU16(this->rangeShift) ||
   924        !SerializeParts(this->ranges, out) ||
   925        !SerializeParts(this->oRuleMap, out) ||
   926        !SerializeParts(this->ruleMap, out) ||
   927        !out->WriteU8(this->minRulePreContext) ||
   928        !out->WriteU8(this->maxRulePreContext) ||
   929        !SerializeParts(this->startStates, out) ||
   930        !SerializeParts(this->ruleSortKeys, out) ||
   931        !SerializeParts(this->rulePreContext, out) ||
   932        (parent->version >> 16 >= 2 &&
   933         (!out->WriteU8(this->collisionThreshold) ||
   934          !out->WriteU16(this->pConstraint))) ||
   935        !SerializeParts(this->oConstraints, out) ||
   936        !SerializeParts(this->oActions, out) ||
   937        !SerializeParts(this->stateTrans, out) ||
   938        (parent->version >> 16 >= 2 &&
   939         (!out->WriteU8(this->reserved2) ||
   940          !SerializeParts(this->passConstraints, out))) ||
   941        !SerializeParts(this->ruleConstraints, out) ||
   942        !SerializeParts(this->actions, out) ||
   943        !SerializeParts(this->dActions, out) ||
   944        !SerializeParts(this->dStates, out) ||
   945        !SerializeParts(this->dCols, out)) {
   946      return parent->Error("SILPass: Failed to write");
   947    }
   948    return true;
   949  }
