   956    if (!table.ReadU16(&this->lastId)) {
   957      return parent->Error("PassRange: Failed to read lastId");
   958    }
   959    if (!table.ReadU16(&this->colId)) {
   960      return parent->Error("PassRange: Failed to read colId");
   961    }
   962    return true;
   963  }
